import{_ as d,r as i,o as l,c as s,b as e,d as r,a as n,e as o}from"./app-84ed3530.js";const h={},c={href:"https://github.com/VanGong1999/FDE",target:"_blank",rel:"noopener noreferrer"};function p(b,t){const a=i("ExternalLinkIcon");return l(),s("div",null,[t[3]||(t[3]=e("h1",{id:"fde-交付方法论-discover-→-design-→-deploy-→-review",tabindex:"-1"},[e("a",{class:"header-anchor",href:"#fde-交付方法论-discover-→-design-→-deploy-→-review","aria-hidden":"true"},"#"),r(" FDE 交付方法论：Discover → Design → Deploy → Review")],-1)),e("blockquote",null,[e("p",null,[t[1]||(t[1]=r("本文整理自开源知识库 ",-1)),e("a",c,[t[0]||(t[0]=r("VanGong1999/FDE",-1)),n(a)]),t[2]||(t[2]=r("（MIT License）的「交付方法论」部分。",-1))])]),t[4]||(t[4]=o(`<p>DDDR 是 FDE 现场工作的<strong>主骨架</strong>。目标：能说清每个阶段的<strong>入口、动作、出口、产物</strong>，并避免阶段跳跃——最常见的翻车是 Discover 没做完就 Deploy。</p><hr><h2 id="_1-总览" tabindex="-1"><a class="header-anchor" href="#_1-总览" aria-hidden="true">#</a> 1. 总览</h2><div class="language-mermaid line-numbers-mode" data-ext="mermaid"><pre class="language-mermaid"><code><span class="token keyword">flowchart</span> LR
  D1<span class="token text string">[&quot;Discover&lt;br/&gt;发现&quot;]</span> <span class="token arrow operator">--&gt;</span> D2<span class="token text string">[&quot;Design&lt;br/&gt;设计&quot;]</span>
  D2 <span class="token arrow operator">--&gt;</span> D3<span class="token text string">[&quot;Deploy&lt;br/&gt;部署&quot;]</span>
  D3 <span class="token arrow operator">--&gt;</span> R<span class="token text string">[&quot;Review&lt;br/&gt;复盘&quot;]</span>
  R <span class="token arrow operator">-.-&gt;</span><span class="token label property">|新范围或下一场景|</span> D1
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><table><thead><tr><th>阶段</th><th>一句话</th><th>核心问题</th></tr></thead><tbody><tr><td>Discover</td><td>弄清真相</td><td>谁痛？被什么指标衡量？约束是什么？</td></tr><tr><td>Design</td><td>变成可执行计划</td><td>做什么、不做什么、如何证明成功？</td></tr><tr><td>Deploy</td><td>在约束内实现并上线</td><td>权限、数据、集成、培训、观测齐了吗？</td></tr><tr><td>Review</td><td>学习与杠杆</td><td>有效吗？为何？怎样复用/反馈产品？</td></tr></tbody></table><blockquote><p>AI 项目特别容易在 Deploy 前假装 Design 完成——<strong>没有 Eval 计划就不算 Design 完成</strong>。</p></blockquote><hr><h2 id="_2-discover-发现" tabindex="-1"><a class="header-anchor" href="#_2-discover-发现" aria-hidden="true">#</a> 2. Discover（发现）</h2><h3 id="入口条件" tabindex="-1"><a class="header-anchor" href="#入口条件" aria-hidden="true">#</a> 入口条件</h3><ul><li>有赞助人（sponsor）或至少一名业务 champion</li><li>能接触到真实用户或一线操作者（不是只有 IT 转述）</li></ul><h3 id="关键动作" tabindex="-1"><a class="header-anchor" href="#关键动作" aria-hidden="true">#</a> 关键动作</h3><ol><li><strong>干系人地图</strong>：出资、使用、否决（安全/法务/IT）、维护四类人</li><li><strong>现状工作流</strong>：用时、工具、例外、失败代价</li><li><strong>数据与权限现实</strong>：在哪、能否出域、质量、新鲜度</li><li><strong>成功的可观测定义</strong>：若只能选一个指标，是什么？</li><li><strong>非目标</strong>：明确「这次不解决什么」</li></ol><h3 id="出口检查" tabindex="-1"><a class="header-anchor" href="#出口检查" aria-hidden="true">#</a> 出口检查</h3><ul><li><input type="checkbox" class="task-checkbox" disabled> 能用一句话说清「为谁、解决什么可测问题」</li><li><input type="checkbox" class="task-checkbox" disabled> 知道最大技术/组织风险各一条</li><li><input type="checkbox" class="task-checkbox" disabled> 赞助人认可问题陈述（哪怕方案未定）</li></ul><p>产物：<strong>发现纪要</strong>（问题陈述、用户、指标、约束、风险、开放问题）。</p><hr><h2 id="_3-design-设计" tabindex="-1"><a class="header-anchor" href="#_3-design-设计" aria-hidden="true">#</a> 3. Design（设计）</h2><h3 id="入口条件-1" tabindex="-1"><a class="header-anchor" href="#入口条件-1" aria-hidden="true">#</a> 入口条件</h3><ul><li>Discover 出口检查通过</li><li>已对真实数据做过抽样</li></ul><h3 id="关键动作-1" tabindex="-1"><a class="header-anchor" href="#关键动作-1" aria-hidden="true">#</a> 关键动作</h3><ol><li><strong>方案选项</strong>（至少 2 个）：必须包含「不用 LLM」的选项</li><li><strong>架构草图</strong>：数据流、权限、人机回环、失败降级</li><li><strong>Eval 设计</strong>：golden set 从哪来、量规是什么</li><li><strong>试点切片</strong>：用户群 × 文档/流程子集 × 时间盒</li><li><strong>成本与延迟预算</strong></li><li><strong>安全与合规审查清单</strong></li></ol><h3 id="出口检查-1" tabindex="-1"><a class="header-anchor" href="#出口检查-1" aria-hidden="true">#</a> 出口检查</h3><ul><li><input type="checkbox" class="task-checkbox" disabled> 成功标准可测，且与业务指标挂钩</li><li><input type="checkbox" class="task-checkbox" disabled> 有明确非目标与时间盒</li><li><input type="checkbox" class="task-checkbox" disabled> 安全/IT 已看到权限与数据流（至少知情）</li></ul><p>产物：<strong>设计一页纸</strong>、POC/Pilot 验收标准（可勾选）、风险登记与缓解。</p><hr><h2 id="_4-deploy-部署" tabindex="-1"><a class="header-anchor" href="#_4-deploy-部署" aria-hidden="true">#</a> 4. Deploy（部署）</h2><h3 id="入口条件-2" tabindex="-1"><a class="header-anchor" href="#入口条件-2" aria-hidden="true">#</a> 入口条件</h3><ul><li>Design 验收标准已书面确认</li><li>环境、密钥、网络路径已打通，或有明确 blocker 升级</li></ul><h3 id="关键动作-2" tabindex="-1"><a class="header-anchor" href="#关键动作-2" aria-hidden="true">#</a> 关键动作</h3><ol><li>实现与集成（迭代，但每次迭代可演示）</li><li>评测闭环：改 → 跑 eval → 看失败案例</li><li>权限、审计、日志、告警</li><li>用户培训与 Runbook</li><li>分阶段 rollout：<strong>影子模式 → 建议模式 → 自动模式</strong></li><li>交接计划（谁值班？）</li></ol><h3 id="出口检查-2" tabindex="-1"><a class="header-anchor" href="#出口检查-2" aria-hidden="true">#</a> 出口检查</h3><ul><li><input type="checkbox" class="task-checkbox" disabled> 达到书面验收线，或有明确「未达线但不扩大范围」的决策</li><li><input type="checkbox" class="task-checkbox" disabled> 回滚路径可用</li><li><input type="checkbox" class="task-checkbox" disabled> 至少一名客户侧人员能独立完成主路径操作</li></ul><p>产物：运行系统、观测看板与 on-call 说明、用户启用材料。</p><hr><h2 id="_5-review-复盘" tabindex="-1"><a class="header-anchor" href="#_5-review-复盘" aria-hidden="true">#</a> 5. Review（复盘）</h2><h3 id="入口条件-3" tabindex="-1"><a class="header-anchor" href="#入口条件-3" aria-hidden="true">#</a> 入口条件</h3><ul><li>试点或生产运行过一个约定窗口（如 2–4 周）</li></ul><h3 id="关键动作-3" tabindex="-1"><a class="header-anchor" href="#关键动作-3" aria-hidden="true">#</a> 关键动作</h3><ol><li>对照指标：量与质（含失败案例抽样）</li><li>用户访谈：采用障碍</li><li>技术债与成本复盘</li><li><strong>模式化</strong>：哪些可进解决方案库？</li><li><strong>产品反馈</strong>：平台缺什么？</li><li>决定：扩大 / 维持 / 停掉 / 改方向</li></ol><h3 id="出口检查-3" tabindex="-1"><a class="header-anchor" href="#出口检查-3" aria-hidden="true">#</a> 出口检查</h3><ul><li><input type="checkbox" class="task-checkbox" disabled> 有「下一轮 Discover」的输入，或明确结项</li><li><input type="checkbox" class="task-checkbox" disabled> 知识不独享在你个人笔记本里</li></ul><hr><h2 id="_6-与六阶段工作流的对照" tabindex="-1"><a class="header-anchor" href="#_6-与六阶段工作流的对照" aria-hidden="true">#</a> 6. 与六阶段工作流的对照</h2><p>公开资料里也常见六阶段版本，与 DDDR 一一对应，便于面试口述：</p><table><thead><tr><th>六阶段</th><th>对应 DDDR</th><th>核心技能提醒</th></tr></thead><tbody><tr><td>Discover</td><td>Discover</td><td>商业理解 + 技术判断；客户口述需求常不是瓶颈</td></tr><tr><td>Design</td><td>Design</td><td>明确做/不做；基础设施、数据、安全、失败模式</td></tr><tr><td>Build</td><td>Deploy（实现）</td><td>RAG、Eval、脏 API 兼容；生产可靠重于 Demo</td></tr><tr><td>Deploy</td><td>Deploy（上线）</td><td>私有化/云、合规、文化阻力</td></tr><tr><td>Prove</td><td>Review</td><td>把效果换成钱/风险/时间；ROI 是建立信任的关键</td></tr><tr><td>Scale</td><td>Review → 下一轮 Discover</td><td>复制到相邻部门；监控漂移与成本；模式回流产品</td></tr></tbody></table><hr><h2 id="_7-示例-把「智能客服」塞进-dddr" tabindex="-1"><a class="header-anchor" href="#_7-示例-把「智能客服」塞进-dddr" aria-hidden="true">#</a> 7. 示例：把「智能客服」塞进 DDDR</h2><table><thead><tr><th>阶段</th><th>例子</th></tr></thead><tbody><tr><td>Discover</td><td>真正痛点是「首响」还是「一次解决率」？工单系统能否写回？</td></tr><tr><td>Design</td><td>先做「检索知识库 + 坐席助手」而非全自动回复；定义 50 条黄金问答</td></tr><tr><td>Deploy</td><td>影子模式建议回复；坐席一键采纳；记录采纳率</td></tr><tr><td>Review</td><td>采纳率 35% → 分析拒绝原因；扩大品类或停掉自动发送</td></tr></tbody></table><p><strong>保险公司案例</strong>（可当面试 Decomposition 素材）：客户以为理赔慢是「平台问题」→ 发现实为理赔前文档人工审核 → Design 做「读文档 + 对照保单 + 结构化摘要」，<strong>不</strong>自动做理赔决策 → Prove 用「数小时 → 数分钟」与金额叙事。</p><hr><h2 id="_8-poc-到生产的四个跨越" tabindex="-1"><a class="header-anchor" href="#_8-poc-到生产的四个跨越" aria-hidden="true">#</a> 8. POC 到生产的四个跨越</h2><p>POC 与生产系统之间隔着四条沟，FDE 的核心工作就是逐一跨过：</p><table><thead><tr><th>沟</th><th>POC 里</th><th>生产里</th></tr></thead><tbody><tr><td>数据</td><td>干净的样例集</td><td>多源、脏、有权限、会漂移</td></tr><tr><td>质量</td><td>「看起来不错」</td><td>golden set + 回归评测 + 失败分析</td></tr><tr><td>安全</td><td>没人管</td><td>提示注入防护、PII 脱敏、审计日志</td></tr><tr><td>运营</td><td>自己演示</td><td>用户培训、值班、SLA、成本核算</td></tr></tbody></table><h3 id="常见反模式-踩坑清单" tabindex="-1"><a class="header-anchor" href="#常见反模式-踩坑清单" aria-hidden="true">#</a> 常见反模式（踩坑清单）</h3><ul><li><strong>Demo 驱动开发</strong>：为演示效果调 prompt，从未建立可回归的评测集</li><li><strong>范围蔓延</strong>：客户一句「顺便也帮我……」就答应，不做范围决策记录</li><li><strong>全自动执念</strong>：明明该 HITL 的场景硬做全自动，一次事故毁掉全部信任</li><li><strong>指标失焦</strong>：用「答了」衡量，不用「答对且被采纳」衡量</li><li><strong>知识独享</strong>：方案、坑、模板都存在个人笔记本，无法复用</li><li><strong>跳过安全/IT</strong>：上线前才发现数据不能出域，项目归零</li></ul><hr><h2 id="_9-阶段节奏" tabindex="-1"><a class="header-anchor" href="#_9-阶段节奏" aria-hidden="true">#</a> 9. 阶段节奏</h2><p>现实中阶段会重叠，但遵守：</p><ul><li><strong>允许</strong>：Deploy 早期同时补 Discover 细节</li><li><strong>禁止</strong>：用 Demo 欢呼跳过 Eval；用「先做了再说」跳过安全</li><li><strong>时间盒</strong>：Discover 1–2 周、窄 Pilot 2–6 周是常见量级（视企业采购与数据就绪度而变）</li></ul><hr><h2 id="_10-读完马上做" tabindex="-1"><a class="header-anchor" href="#_10-读完马上做" aria-hidden="true">#</a> 10. 读完马上做</h2><ul><li><input type="checkbox" class="task-checkbox" disabled> 默写四阶段出口检查</li><li><input type="checkbox" class="task-checkbox" disabled> 选一个你过去的项目，标出它实际停在哪一阶段</li><li><input type="checkbox" class="task-checkbox" disabled> 用六阶段表给同一项目再标一遍，看缺口是否在 Prove / Scale</li></ul>`,62))])}const u=d(h,[["render",p],["__file","fde-02-delivery.html.vue"]]);export{u as default};
